{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Moexipril, a high-transfer prodrug with an ester/amide polar framework, showed no detectable brain radioactivity after systemic administration in rats and dogs, demonstrating that polar/charged systemic molecules can be effectively excluded from the CNS; the query's amide and permanent phosphonium charge are at least as restrictive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sacubitril in cynomolgus monkeys had a CSF:plasma ratio ≤0.0044 and brain:plasma ratio ≤0.0326, providing direct primate evidence of negligible CNS penetration for a lipophilic but polar/ionizable drug; the query's permanently charged phosphonium group is a stronger BBB liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The fesoterodine metabolite 5-HMT, a P-gp substrate, showed low brain penetration in rats, indicating that transporter-mediated efflux can restrict CNS access for lipophilic cationic/amine-containing drugs; the query's large lipophilic phosphonium cation is likely subject to similar or greater efflux restriction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "HDACi 109 exhibited a brain/plasma ratio of only 0.15 in rats and was classified as a poor penetrant, supporting the pattern that even moderately lipophilic compounds with polar/charged features fail to achieve meaningful CNS exposure; the query has additional permanent charge and high polar surface area.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, permanently charged triphenylphosphonium amide with multiple hydrogen-bond donors and a long lipophilic tail. All high-transfer experimental analogues show negligible brain/CSF penetration after systemic dosing, including direct primate CSF/brain measurements and P-gp substrate data. The permanent positive charge and polar amide surface are strong BBB liabilities, and no evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF measurement exists for the exact query or a close triphenylphosphonium analogue.",
    "No data on active uptake, efflux transporter profile, or plasma protein binding for the query.",
    "The phosphonium charge is not masked by a prodrug strategy, so systemic CNS access is expected to be poor."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

